using DlnRenderer.Dlna.AvTransport;
using DlnRenderer.Dlna.Soap;
using DlnRenderer.Dlna.Tests.Support;
using System.Xml.Linq;

namespace DlnRenderer.Dlna.Tests;

/// <summary>
/// Keeps the advertised sink list honest (stage D, D2).
/// </summary>
/// <remarks>
/// The list used to claim 392 formats: audio codecs under a <c>video/*</c> MIME, containers
/// libavcodec has no decoder for (RealMedia, MIDI, ATRAC3, QCELP), DRM-protected profiles and
/// still images the renderer cannot display. Stage D measured what the engine really plays
/// (<c>docs/media-matrix.md</c>, generated by <c>tools/media-compat/measure-media.ps1</c>) and the
/// list was cut to what is defensible. These assertions stop the removed categories from coming
/// back with the next copy-paste from another device's protocol list.
/// </remarks>
public class SinkProtocolInfoTests
{
    private static string Sink()
    {
        var service = new ConnectionManagerService();
        var document = XDocument.Parse(service.Handle(
            SoapBody.Parse(SoapNamespaces.ConnectionManagerServiceType, "GetProtocolInfo")));
        var body = document.Root!.Elements().Single(e => e.Name.LocalName == "Body");
        var response = body.Elements().Single();
        return response.Elements().Single(e => e.Name.LocalName == "Sink").Value;
    }

    [Fact]
    public void Every_measured_playable_format_is_still_declared()
    {
        var sink = Sink();

        // One entry per container that tools/media-compat measured as playable; removing any of
        // these would silently make real files un-castable.
        string[] required =
        [
            "http-get:*:video/mp4",
            "http-get:*:video/x-matroska",
            "http-get:*:video/webm",
            "http-get:*:video/quicktime",
            "http-get:*:video/x-ms-avi",
            "http-get:*:video/MP2T",
            "http-get:*:video/vnd.dlna.mpeg-tts",
            "http-get:*:video/x-flv",
            "http-get:*:video/swf",
            "http-get:*:audio/mpeg",
            "http-get:*:audio/mp4",
            "http-get:*:audio/flac",
            "http-get:*:audio/ogg",
            "http-get:*:audio/wav",
            "http-get:*:audio/ac3",
        ];

        foreach (var entry in required)
        {
            Assert.Contains(entry, sink, StringComparison.OrdinalIgnoreCase);
        }
    }

    [Fact]
    public void Undecodable_and_mislabelled_formats_are_not_declared()
    {
        var sink = Sink();

        string[] forbidden =
        [
            // Audio content declared with a video/* MIME.
            "video/mp3", "video/mpeg3", "video/wma", "video/x-ms-wma", "video/wav", "video/m4a",
            "video/flac", "video/aiff", "video/ape", "video/aac", "video/ac3",
            // No decoder exists in libavcodec (RealMedia, MIDI, ATRAC3, QCELP).
            "video/rm", "video/x-rm", "video/rmvb", "video/x-rmvb", "video/x-pn-realvideo",
            "audio/ra", "audio/x-ra", "audio/x-realaudio", "audio/vnd.rn-realaudio",
            "audio/midi", "audio/x-midi", "audio/mid", "audio/x-atrac3", "audio/vnd.qcelp",
            // Placeholder values copied from another device.
            "video/unknown", "audio/unknown",
        ];

        foreach (var entry in forbidden)
        {
            // Match the MIME as a whole field, so "video/mp3" cannot hide behind "video/mp3x".
            Assert.DoesNotContain(
                $":{entry}:",
                sink,
                StringComparison.OrdinalIgnoreCase);
        }
    }

    [Fact]
    public void No_drm_protected_profile_is_declared()
    {
        var sink = Sink();

        // The renderer cannot decrypt DRM content; claiming those profiles makes a control point
        // offer a cast that is guaranteed to fail.
        Assert.DoesNotContain("WMDRM_", sink, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public void Still_images_are_not_declared_until_there_is_a_slideshow()
    {
        var sink = Sink();

        // mpv shows a still frame and immediately ends it (keep-open=no), which looks like a
        // broken cast. Photo casting belongs with the slideshow feature, not before it.
        Assert.DoesNotContain(":image/", sink, StringComparison.OrdinalIgnoreCase);
    }
}
